div.script:
odoo.define('share_view.loader', function (require) {
"use strict";
const { registry } = require("@web/core/registry");
const { session } = require("@web/session");

const actionService = require("@web/webclient/actions").actionService;
document.addEventListener("DOMContentLoaded", async () => {
const container = document.getElementById("shared_view");
if (container) {
const data = container.dataset.oeAction;
if (data) {
const parsed = JSON.parse(data);
const action = JSON.parse(parsed.action);

// Call doAction
const env = odoo.__DEBUG__.services.env; // quick hack for demo
const actionService = env.services.action;
actionService.doAction(action);
}
}
});
});
